bool correctBracketing(String brackets) {
  if (brackets.isEmpty || brackets.length % 2 != 0) return false;

  int openCount = 0; // Count of opening brackets
  int closeCount = 0; // Count of closing brackets

  for (int i = 0; i < brackets.length; ++i) {
    final char = brackets[i];

    if (char == '(') {
      openCount++;
    } else if (char == ')') {
      closeCount++;

      // Check if the current number of closing brackets exceeds the total possible openings
      if (closeCount > openCount) {
        return false;
      }
    }
  }

  // After processing all characters, check that both counts are equal
  return openCount == closeCount;
}

