String _binaryToHex(String binary) {
  var hexDigits = '';
  for (var i = 0; i < binary.length; i += 4) {
    String nibble = binary.substring(i, i + 4);
    int value = int.parse(nibble, radix: 2);
    if (value > 15) throw ArgumentError('Invalid binary string');
    hexDigits += value.toRadixString(16).toUpperCase();
  }
  return hexDigits;
