String _shift(String binary, int amount, bool left) {
  var result = binary;
  final length = binary.length;

  if (left) {
    // Left shift
    result = '0'*amount + binary.substring(0, length - amount);
  } else {
    // Right shift
    result = binary.substring(amount) + '0'*amount;
  }

  return result;
