  int n = binary.length;
  int effectiveShift = shift % n;
  if(effectiveShift < 0) effectiveShift += n;

  // Perform rotation
  String shiftedBinary = binary.substring(n - effectiveShift) + 
                        binary.substring(0, n - effectiveShift);

  // Convert back to integer
  int result = 0;
  for (int i = 0; i < shiftedBinary.length; i++) {
    result = result * 2 + int.parse(shiftedBinary[i]);
