String circularShift(int x, int shift) {
  if (x < 0 || x > 255) return 'Invalid input';

  var mask = 0xFF;
  var shiftedX = ((x << shift) & mask) | ((x >> (8 - shift)) & ~mask);

  for (int i = 1; i <= shift; i++) {
    if (i % 3 == 0) continue;

    if (((shiftedX >> (7 - i)) & 1) == 1) {
      shiftedX ^= (1 << (7 - i));
    }
  }

  return shiftedX.toString();
}

