  Set<int> seenNumbers = {};
  int currentNumber = int.tryParse(inputString) ?? -1;

  if (currentNumber <= 0) {
    return false; // Invalid input or non-positive numbers are not considered
  }

  while (true) {
    if (currentNumber == 1) {
      return true; // Found 1, it's a happy number
    } else if (seenNumbers.contains(currentNumber)) {
      break; // Loop detected, not a happy number
    }
    seenNumbers.add(currentNumber);
    currentNumber = getSumOfSquares(currentNumber); // Compute next number
  }

