int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0 || capacity <= 0) return 0;

  final cols = grid[0].length;
  // Helper function to check if a cell is within bounds
  bool isValid(int r, int c) => r >= 0 && r < rows && c >= 0 && c < cols;

  int fillLevel = 0;
  Queue<int> queue = Queue();

  // Start from the top-left corner
  queue.add(0);
  Set<int> visited = {0};

  while (queue.isNotEmpty) {
    final current = queue.removeFirst();
    final row = current ~/ cols;
    final col = current % cols;

    for (int dr = -1; dr <= 1; dr++) {
      for (int dc = -1; dc <= 1; dc++) {
        if (dr == 0 && dc == 0) continue; // Skip current cell
        final nextRow = row + dr;
        final nextCol = col + dc;
        if (isValid(nextRow, nextCol)) {
          final neighborIndex = nextRow * cols + nextCol;
          if (!visited.contains(neighborIndex)) {
            if (grid[nextRow][nextCol] > 0) {
              fillLevel += 1;
              if (fillLevel > capacity) {
                return fillLevel - 1;
              }
            } else {
              queue.add(neighborIndex);
              visited.add(neighborIndex);
            }
          }
        }
      }
    }
  }

  return fillLevel;
}

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Initialize the DP table
  var dp = List.generate(rows + 1, (_) => List.filled(cols + 1, 0));

  for (var i = 0; i <= rows; i++) {
    for (var j = 0; j <= cols; j++) {
      if (i == 0 || j == 0) {
        dp[i][j] = 0;
      } else {
        dp[i][j] = dp[i - 1][j];

        if (grid[i - 1][j - 1] != 0) {
          var cost = grid[i - 1][j - 1];
          if (capacity >= cost && dp[i - 1][j - 1] != -1) {
            dp[i][j] = max(dp[i][j], dp[i - 1][j - 1] + cost);
          }
        }
      }
    }
  }

  return dp[rows][cols];
}

