class PriorityQueue<T extends Comparable<T>> {
  late final _comparator;
  final _heap = <T>[];

  PriorityQueue(Function comparator) : _comparator = comparator;

  get size => _heap.length;

  void add(T element) {
    _heap.add(element);
    _siftUp(_heap.length - 1);
  }

  T? peek() => _heap.isEmpty ? null : _heap[0];

  T remove() {
    if (_heap.isEmpty) throw Exception('Cannot remove from empty priority queue');

    final value = _heap[0];
    _heap[0] = _heap.last;
    _heap.removeLast();
    _siftDown(0);
    return value;
  }

  bool isEmpty() => _heap.isEmpty;

  void _siftUp(int index) {
    while (index > 0) {
      final parentIndex = (index - 1) ~/ 2;
      if (_comparator(_heap[index], _heap[parentIndex]) >= 0) break;

      _swap(index, parentIndex);
      index = parentIndex;
    }
  }

  void _siftDown(int index) {
    final length = _heap.length;
    var childIndex = 2 * index + 1;

    while (childIndex < length) {
      if (childIndex + 1 < length &&
          _comparator(_heap[childIndex + 1], _heap[childIndex]) > 0) {
        childIndex++;
      }

      if (_comparator(_heap[index], _heap[childIndex]) >= 0) break;

      _swap(index, childIndex);
      index = childIndex;
      childIndex = 2 * index + 1;
    }
  }

  void _swap(int a, int b) {
    final temp = _heap[a];
    _heap[a] = _heap[b];
    _heap[b] = temp;
  }
}

