  List<int> dp = List.filled(rows * cols + 1, -1);

  void dfs(int i, int j, int steps, int sum) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || steps > k) return;

    // Convert to index for DP array
    var idx = i * cols + j;
    if (dp[idx] != -1 && dp[idx] <= sum) return; // Already visited with better or equal value

    dp[idx] = sum;

    // Go up
    dfs(i-1, j, steps+1, sum + grid[i][j]);
    // Go down
    dfs(i+1, j, steps+1, sum + grid[i][j]);
    // Go left
    dfs(i, j-1, steps+1, sum + grid[i][j]);
    // Go right
    dfs(i, j+1, steps+1, sum + grid[i][j]);
  }

  dfs(0, 0, 0, 0);
  return dp;
}

