// Helper function to find the minimal path by backtracking
void backtrack(List<List<int>> grid, List<List<int>> dp, int x, int y, int limit, List<int> res) {
  if (x == grid.length - 1 && y == grid[0].length - 1) {
    res.add([grid[x][y]]);
    return;
  }

  // Try moving down
  if (x + 1 < grid.length && dp[x][y] > dp[x+1][y]) {
    backtrack(grid, dp, x + 1, y, limit, res);
  }

  // Try moving right
  if (y + 1 < grid[0].length && dp[x][y] > dp[x][y+1]) {
    backtrack(grid, dp, x, y + 1, limit, res);
  }
}

