import 'package:stack_trace/stack_trace.dart';

class NestedStringValidator {
  static bool validate(String input) {
    final stackTrace = StackTrace.current;
    print('Validation started with trace:\n$stackTrace');

    try {
      return _isNested(input);
    } catch (e) {
      print('Error occurred during validation: $e');
      rethrow;
    }
  }

  static bool _isNested(String string) {
    if (string.isEmpty) return false;

    int depth = 0;
    for (int i = 0; i < string.length && depth >= 0; i++) {
      if (string[i] == '(') depth++;
      else if (string[i] == ')') depth--;

      if (depth < 0) {
        throw Exception("Unmatched closing parenthesis at position $i");
      }
    }

    return depth == 0;
  }
}

void main() {
  String test1 = "(a(b)c)";
  String test2 = "((()))";
  String test3 = "(()"; 
  String test4 = ")(", 
  String test5 = "()())";

  print(NestedStringValidator.validate(test1)); // true
  print(NestedStringValidator.validate(test2)); // true
  print(NestedStringValidator.validate(test3)); // false
  print(NestedStringValidator.validate(test4)); // false
  print(NestedStringValidator.validate(test5)); // false
}
